CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, sha256 TEXT NOT NULL, applied_at_utc TEXT NOT NULL);
CREATE TABLE locations(id TEXT PRIMARY KEY, name TEXT NOT NULL, latitude REAL NOT NULL, longitude REAL NOT NULL, timezone TEXT NOT NULL);
CREATE TABLE weather_sources(id TEXT PRIMARY KEY, name TEXT NOT NULL, reference_url TEXT NOT NULL, kind TEXT NOT NULL);
CREATE TABLE weather_models(id TEXT PRIMARY KEY, source_id TEXT NOT NULL REFERENCES weather_sources(id), name TEXT NOT NULL);
CREATE TABLE model_versions(id TEXT PRIMARY KEY, model_id TEXT NOT NULL REFERENCES weather_models(id), provider_version TEXT, evidence_url TEXT);
CREATE TABLE system_versions(id TEXT PRIMARY KEY, pipeline_version TEXT NOT NULL, schema_version INTEGER NOT NULL, git_commit TEXT);
CREATE TABLE pipeline_executions(id TEXT PRIMARY KEY, location_id TEXT NOT NULL REFERENCES locations(id), collected_at_utc TEXT NOT NULL, system_version TEXT NOT NULL REFERENCES system_versions(id), status TEXT NOT NULL, manifest_hash TEXT NOT NULL);
CREATE TABLE raw_assets(sha256 TEXT PRIMARY KEY, relative_path TEXT NOT NULL, byte_count INTEGER NOT NULL);
CREATE TABLE forecast_runs(id TEXT PRIMARY KEY, execution_id TEXT NOT NULL REFERENCES pipeline_executions(id), location_id TEXT NOT NULL REFERENCES locations(id), model_id TEXT NOT NULL REFERENCES weather_models(id), model_version_id TEXT REFERENCES model_versions(id), product TEXT NOT NULL, initialization_utc TEXT, collected_at_utc TEXT NOT NULL, available_at_utc TEXT, grid_latitude REAL, grid_longitude REAL, elevation_m REAL, spatial_resolution_km REAL, original_timezone TEXT, source_url TEXT NOT NULL, query_json TEXT NOT NULL, raw_sha256 TEXT NOT NULL REFERENCES raw_assets(sha256), collector_version TEXT NOT NULL, temporal_basis TEXT NOT NULL, UNIQUE(location_id,product,model_id,raw_sha256,query_json));
CREATE TABLE forecast_values(run_id TEXT NOT NULL REFERENCES forecast_runs(id), valid_at_utc TEXT NOT NULL, variable TEXT NOT NULL, original_unit TEXT, unit TEXT, interval_start_utc TEXT, interval_end_utc TEXT, lead_hours REAL, lead_basis TEXT, original_value REAL, value REAL, qc TEXT NOT NULL, missing INTEGER NOT NULL, PRIMARY KEY(run_id,valid_at_utc,variable,lead_basis));
CREATE TABLE ensemble_members(model_id TEXT NOT NULL REFERENCES weather_models(id), member_id TEXT NOT NULL, PRIMARY KEY(model_id,member_id));
CREATE TABLE ensemble_forecasts(run_id TEXT NOT NULL REFERENCES forecast_runs(id), valid_at_utc TEXT NOT NULL, variable TEXT NOT NULL, member_id TEXT NOT NULL, original_unit TEXT, unit TEXT, interval_start_utc TEXT, interval_end_utc TEXT, lead_hours REAL, lead_basis TEXT, original_value REAL, value REAL, qc TEXT NOT NULL, missing INTEGER NOT NULL, PRIMARY KEY(run_id,valid_at_utc,variable,member_id,lead_basis));
CREATE TABLE observing_stations(id TEXT PRIMARY KEY, institution TEXT NOT NULL, name TEXT NOT NULL, latitude REAL NOT NULL, longitude REAL NOT NULL, altitude_m REAL, timezone TEXT NOT NULL, identity_status TEXT NOT NULL, evidence_url TEXT NOT NULL, metadata_json TEXT NOT NULL);
CREATE TABLE observations(id TEXT PRIMARY KEY, station_id TEXT NOT NULL REFERENCES observing_stations(id), location_id TEXT NOT NULL REFERENCES locations(id), valid_at_utc TEXT NOT NULL, variable TEXT NOT NULL, unit TEXT NOT NULL, interval_start_utc TEXT, interval_end_utc TEXT, original_value REAL, value REAL, qc TEXT NOT NULL, reference_quality TEXT NOT NULL, raw_sha256 TEXT NOT NULL REFERENCES raw_assets(sha256), available_at_utc TEXT, UNIQUE(station_id,valid_at_utc,variable,raw_sha256));
CREATE TABLE reanalysis_values(id TEXT PRIMARY KEY, location_id TEXT NOT NULL REFERENCES locations(id), source_id TEXT NOT NULL REFERENCES weather_sources(id), valid_at_utc TEXT NOT NULL, variable TEXT NOT NULL, unit TEXT NOT NULL, interval_start_utc TEXT, interval_end_utc TEXT, value REAL, qc TEXT NOT NULL, raw_sha256 TEXT NOT NULL REFERENCES raw_assets(sha256));
CREATE TABLE data_quality_flags(id TEXT PRIMARY KEY, run_id TEXT REFERENCES forecast_runs(id), record_key TEXT NOT NULL, code TEXT NOT NULL, detail TEXT NOT NULL);
CREATE TABLE forecast_verifications(id TEXT PRIMARY KEY, location_id TEXT NOT NULL REFERENCES locations(id), model_id TEXT NOT NULL, variable TEXT NOT NULL, horizon TEXT NOT NULL, station_id TEXT NOT NULL REFERENCES observing_stations(id), reference_quality TEXT NOT NULL, n INTEGER NOT NULL, metrics_json TEXT NOT NULL, dataset_sha256 TEXT NOT NULL, formula_version TEXT NOT NULL, created_at_utc TEXT NOT NULL);
CREATE TABLE calibration_datasets(id TEXT PRIMARY KEY, location_id TEXT NOT NULL REFERENCES locations(id), sha256 TEXT NOT NULL, split_json TEXT NOT NULL, reference_quality TEXT NOT NULL, created_at_utc TEXT NOT NULL);
CREATE TABLE calibration_models(id TEXT PRIMARY KEY, dataset_id TEXT NOT NULL REFERENCES calibration_datasets(id), method TEXT NOT NULL, version TEXT NOT NULL, parameters_json TEXT NOT NULL, status TEXT NOT NULL);
CREATE TABLE calibration_predictions(id TEXT PRIMARY KEY, calibration_model_id TEXT NOT NULL REFERENCES calibration_models(id), run_id TEXT NOT NULL REFERENCES forecast_runs(id), valid_at_utc TEXT NOT NULL, variable TEXT NOT NULL, value REAL, provenance_json TEXT NOT NULL);
CREATE TABLE model_evaluations(id TEXT PRIMARY KEY, calibration_model_id TEXT NOT NULL REFERENCES calibration_models(id), split TEXT NOT NULL, n INTEGER NOT NULL, metrics_json TEXT NOT NULL, created_at_utc TEXT NOT NULL);
CREATE TABLE ai_explanations(id TEXT PRIMARY KEY, provider TEXT NOT NULL, model TEXT, prompt_version TEXT NOT NULL, input_sha256 TEXT NOT NULL, created_at_utc TEXT NOT NULL, response_json TEXT NOT NULL, validation_status TEXT NOT NULL, usage_json TEXT, error TEXT);
CREATE INDEX forecast_valid ON forecast_values(variable,valid_at_utc);
CREATE INDEX ensemble_valid ON ensemble_forecasts(variable,valid_at_utc);
CREATE INDEX obs_valid ON observations(location_id,variable,valid_at_utc);
